def is_valid(grid, n):
    for i in range(n):
        for j in range(n):
            count = 0
            if i > 0 and grid[i-1][j] == grid[i][j]:
                count += 1
            if i < n-1 and grid[i+1][j] == grid[i][j]:
                count += 1
            if j > 0 and grid[i][j-1] == grid[i][j]:
                count += 1
            if j < n-1 and grid[i][j+1] == grid[i][j]:
                count += 1
            if count != 2:
                return False
    return True

def fill_grid(grid, n):
    for i in range(n):
        for j in range(n):
            if grid[i][j] == '.':
                if (i > 0 and grid[i-1][j] == 'S') or (i < n-1 and grid[i+1][j] == 'S') or \
                   (j > 0 and grid[i][j-1] == 'S') or (j < n-1 and grid[i][j+1] == 'S'):
                    grid[i][j] = 'S'
                else:
                    grid[i][j] = 'G'
    return grid

def main():
    n = int(input().strip())
    grid = [list(input().strip()) for _ in range(n)]

    if is_valid(grid, n):
        print("UNIQUE")
        for row in fill_grid(grid, n):
            print(''.join(row))
        return

    # Try flipping the grid and check again
